import { Injectable, OnInit } from '@angular/core';
import { HttpHeaders, HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
const httpOptions = {
  headers: new HttpHeaders({ 'Content-Type': 'application/json' ,
                              'Fineract-Platform-TenantId' : 'default',
                              'Authorization' : 'Basic bWlmb3M6cGFzc3dvcmQ='
                            })
};
@Injectable({
  providedIn: 'root'
})
export class SurveysService  {

  constructor(private http: HttpClient) { }


  getSurveys (): Observable&lt;any[]&gt; {
    console.log(this.http.get&lt;any[]&gt;("<https://demo.openmf.org/fineract-provider/api/v1/surveys?tenantIdentifier=default>",httpOptions)
    .subscribe(data=&gt;console.log(data)));
    return this.http.get&lt;any[]&gt;("<https://demo.openmf.org/fineract-provider/api/v1/surveys?tenantIdentifier=default>",httpOptions);
  }

}

